operation.add:
// ProBG Blog
$this->load->language('extension/module/probg_blog');
$probg_blog = array();
if ($this->user->hasPermission('access', 'extension/probg_blog/article')) {
    $probg_blog[] = array('name' => $this->language->get('text_menu_articles'), 'href' => $this->url->link('extension/probg_blog/article', 'user_token=' . $this->session->data['user_token'], true), 'children' => array());
}
if ($this->user->hasPermission('access', 'extension/probg_blog/category')) {
    $probg_blog[] = array('name' => $this->language->get('text_menu_categories'), 'href' => $this->url->link('extension/probg_blog/category', 'user_token=' . $this->session->data['user_token'], true), 'children' => array());
}
if ($this->user->hasPermission('access', 'extension/module/probg_blog')) {
    $probg_blog[] = array('name' => $this->language->get('text_menu_settings'), 'href' => $this->url->link('extension/module/probg_blog', 'user_token=' . $this->session->data['user_token'], true), 'children' => array());
}
if ($probg_blog) $data['menus'][] = array('id' => 'menu-probg-blog', 'icon' => 'fa-newspaper-o', 'name' => $this->language->get('text_menu_blog'), 'href' => '', 'children' => $probg_blog);

if ($data['route'] == 'extension/module/probg_blog' && ($key == 'route' || $key == 'probg_blog_category_id' || $key == 'probg_blog_article_id')) {
    $probg_blog_query = ($key == 'route') ? $value : $key . '=' . (int)$value;
    $probg_blog_seo = $this->db->query("SELECT * FROM " . DB_PREFIX . "seo_url WHERE `query` = '" . $this->db->escape($probg_blog_query) . "' AND store_id = '" . (int)$this->config->get('config_store_id') . "' AND language_id = '" . (int)$this->config->get('config_language_id') . "'");
    if ($probg_blog_seo->num_rows && $probg_blog_seo->row['keyword']) {
        $url .= '/' . $probg_blog_seo->row['keyword'];
        unset($data[$key]);
    }
}
